def side_pose_x(pos, cs=1, tilt_deg=0.0):
    t = np.radians(tilt_deg)  # tilt approach down by t (rotation about y keeps closing ~vertical)
    a = [np.cos(t), 0, -np.sin(t)]; c = [np.sin(t)*cs, 0, np.cos(t)*cs]
    return rh.pose_from_axes(list(pos), approach=a, closing=c)
