def side_pose_y(pos, from_side, cs=1, tilt_deg=0.0):
    # from_side=-1: gripper on -y side, approach +y ; from_side=+1: approach -y
    t = np.radians(tilt_deg); ay = -from_side
    a = [0, ay*np.cos(t), -np.sin(t)]; c = [0, ay*np.sin(t)*cs, np.cos(t)*cs]
    return rh.pose_from_axes(list(pos), approach=a, closing=c)
